import math

def is_power_of_p(N, p):
    """Checks if N is a positive power of p."""
    if N <= 0:
        return False
    # Since p is prime and > 2, p >= 3.
    if N == 1:
        # 1 = p^0, but powers usually imply positive exponent in this context
        # We require the result to be p^x where x >= 1 usually,
        # but checking if it's strictly a power should suffice.
        return p == 1 # Should not happen as p > 2

    # Repeatedly divide by p
    while N > 1 and N % p == 0:
        N //= p
    return N == 1

def search_solutions(p, max_val):
    solutions = []
    print(f"--- Searching for p = {p} up to a, b = {max_val} ---")

    for a in range(1, max_val + 1):
        for b in range(a, max_val + 1):

            # Condition 1: a^(p-1) + b is a power of p
            try:
                term1 = a**(p - 1) + b
            except OverflowError:
                # Should not happen for max_val=30 and p=5
                continue 

            if is_power_of_p(term1, p):

                # Condition 2: b^(p-1) + a is a power of p
                try:
                    term2 = b**(p - 1) + a
                except OverflowError:
                    continue

                if is_power_of_p(term2, p):
                    solutions.append((p, a, b))
                    print(f"Found solution: ({p}, {a}, {b})")

    return solutions

# Run search for p=3 and p=5 up to a, b = 30
p_values = [3, 5]
max_search = 30
all_solutions = {}

for p in p_values:
    all_solutions[p] = search_solutions(p, max_search)

print("\n=====================================")
