def is_power(n, base):
    if n <= 0:
        return False
    if n == 1:
        # 1 is a power of any base, but in this context p>2, 
        # the result must be p^x where x >= 1 or x=0 if p^0=1.
        # Since a, b >= 1 and p > 2, a^(p-1) + b >= 1^(2) + 1 = 2. So n >= 2.
        return False 

    while n > 1:
        if n % base != 0:
            return False
        n //= base
    return True

def find_solutions(p, limit):
    solutions = []
    for a in range(1, limit + 1):
        for b in range(a, limit + 1):
            # Check condition 1: a^(p-1) + b = p^x
            term1 = a**(p - 1) + b
            is_pow_p_1 = is_power(term1, p)

            if is_pow_p_1:
                # Check condition 2: b^(p-1) + a = p^y
                term2 = b**(p - 1) + a
                is_pow_p_2 = is_power(term2, p)

                if is_pow_p_2:
                    solutions.append((p, a, b))
    return solutions

# Search for p=3 and p=5 up to limit=50
solutions_p3 = find_solutions(3, 50)
solutions_p5 = find_solutions(5, 50)

print("Solutions for p=3 (a, b <= 50):", solutions_p3)
print("Solutions for p=5 (a, b <= 50):", solutions_p5)
